// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint128).max);
        // donate `amount` wei to c through its payable fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // owner (this test contract) calls withdrawAll
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: whenever withdrawAll succeeds, the contract's entire
        // balance must have been transferred out (balance == 0).
        // The mutant deletes the withdraw call, so it succeeds without
        // reducing the balance whenever amount > 0.
        assertTrue(!ok || address(c).balance == 0);
    }
}
